$spaceSamples=$spaceTotal['eclipse']['samples'];
$spaceNorm=static fn(array $v):float=>sqrt($v['x']**2+$v['y']**2+$v['z']**2);
$spaceCompressed=[];
foreach([0,30,60,90,120,150,180] as $sampleIndex){$v=$spaceSamples[$sampleIndex]['moon_position_inertial_km'];$length=$spaceNorm($v);$spaceCompressed[]=[$v['x']/$length*$spaceDefaults['distance_scale'],$v['y']/$length*$spaceDefaults['distance_scale'],$v['z']/$length*$spaceDefaults['distance_scale']];}
foreach($spaceCompressed as $v)realEclipseAssert(abs(sqrt($v[0]**2+$v[1]**2+$v[2]**2)-$spaceDefaults['distance_scale'])<1e-12,'La compresión visual Luna–Tierra dejó de ser constante.');
$spaceSteps=[];for($i=1;$i<count($spaceCompressed);$i++)$spaceSteps[]=sqrt(($spaceCompressed[$i][0]-$spaceCompressed[$i-1][0])**2+($spaceCompressed[$i][1]-$spaceCompressed[$i-1][1])**2+($spaceCompressed[$i][2]-$spaceCompressed[$i-1][2])**2);
