$middleSample=$spaceSamples[90];$theta=deg2rad($middleSample['greenwich_sidereal_angle_degrees']);$inertial=$middleSample['moon_position_inertial_km'];$earthFixed=$middleSample['moon_position_earth_fixed_km'];
realEclipseAssert(abs(cos($theta)*$inertial['x']+sin($theta)*$inertial['y']-$earthFixed['x'])<1e-6&&abs(-sin($theta)*$inertial['x']+cos($theta)*$inertial['y']-$earthFixed['y'])<1e-6,'Los marcos inercial y terrestre no conservan la rotación sidérea esperada.');
